const replacements = new Map<string, string>();

function sourceText(source: unknown, keys: readonly string[]): string {
  let value = source;
  for (const key of keys) {
    if (value === null || typeof value !== "object")
      throw new Error("Invalid compiled presentation source");
    value = Reflect.get(value, key);
  }
  if (typeof value !== "string")
    throw new Error("Invalid compiled presentation text");
  return value;
}

function withSpans(
  text: string,
  spans: readonly { start: number; end: number; tex: string }[],
): string {
  let result = "";
  let previous = 0;
  for (const span of spans) {
    result += text.slice(previous, span.start) + "$" + span.tex + "$";
    previous = span.end;
  }
  return result + text.slice(previous);
}

